UPDATE destination_images
SET is_main = true
WHERE id = #{imageId}

UPDATE destination_images
SET order_index = #{orderIndex}
WHERE id = #{imageId}

UPDATE destinations
SET views = views + 1
WHERE id = #{id}

UPDATE destination_comments
SET likes = likes + 1
WHERE id = #{commentId}

UPDATE destination_comments
SET likes = likes - 1
WHERE id = #{commentId}

UPDATE destination_translations
SET name = #{name},
    description = #{description},
    short_description = #{shortDescription}
WHERE destination_id = #{destinationId} AND language_code = #{languageCode}

mapper.select:
SELECT DISTINCT d.*, c.region_name, t.name, t.short_description AS short_description,
i.image_url AS thumbnail
FROM destinations d
JOIN country_categories c ON d.region_id = c.id
JOIN destination_translations t ON d.id = t.destination_id AND t.language_code = 'ko'
LEFT JOIN destination_images i ON d.id = i.destination_id AND i.is_main = true
JOIN destination_categories dc ON d.id = dc.destination_id
WHERE d.region_id = #{regionId}
AND dc.category_id IN

    #{cid}

AND d.id != #{exceptId}
ORDER BY RAND()
LIMIT #{limit}

SELECT d.id, dt.name AS name, dt.description AS description, dt.short_description AS shortDescription, d.latitude, d.longitude, d.season, d.user_id AS userID, d.region_id AS regionId, ( SELECT image_url FROM destination_images WHERE destination_id = d.id AND is_main = 1 LIMIT 1 ) AS thumbnailPath, cc.region_name AS regionName, (SELECT COUNT(*) FROM bookmarks WHERE target_type = 'DESTINATION' AND target_id = d.id) AS bookmarkCount, d.views FROM destinations d JOIN destination_translations dt ON d.id = dt.destination_id AND dt.language_code = 'ko' JOIN country_categories cc ON d.region_id = cc.id WHERE d.region_id IN
#{id}
ORDER BY d.views DESC
ORDER BY bookmarkCount DESC
ORDER BY d.id ASC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM destinations
WHERE region_id IN

    #{id}
